#pragma once
// `rathena-migrate import`: one-time copy of a legacy MySQL/MariaDB database into PostgreSQL or
// SQLite (DATABASE_DECISION.md increment 4). The servers run on the schema generated by
// tools/sql/mysql2portable.py (sql-files/postgresql/, sql-files/sqlite/), so the copy keeps the
// legacy shape: same tables, same columns, same values.
//
//  1. The source must be a known legacy schema (schema_fingerprint() in known_legacy_baselines(),
//     or a database holding only logs.sql tables).
//  2. The target must be empty (the schema is then created from <schema-dir>/<dialect>/
//     {main,logs,web,roulette_default_data}.sql) or already hold that schema with empty tables
//     (or only the default rows the schema files insert).
//  3. Every table present in both is copied over the intersection of their columns, in batches,
//     one transaction per batch, values bound as parameters. Text is copied byte for byte.
//  4. Identity / AUTOINCREMENT counters continue where the source's AUTO_INCREMENT stood.
//  5. Row counts are compared per table; any difference fails the import.
//
// The MySQL reader itself lives in the tool (tools/mysql_source.cpp): this library has no MySQL
// dependency, and everything here is tested with a fake source.
#include <cstdint>
#include <filesystem>
#include <functional>
#include <iosfwd>
#include <map>
#include <optional>
#include <set>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

#include "rathena/persistence/row.hpp"
#include "rathena/persistence/sql_connection.hpp"

namespace rathena::persistence::migrate {

// ------------------------------------------------------------------ source (legacy MySQL)

/// A source column as information_schema.COLUMNS reports it.
struct SourceColumn {
	std::string name;
	std::string data_type;   ///< DATA_TYPE, lower case: int, varchar, enum, datetime, blob, ...
	std::string column_type; ///< COLUMN_TYPE: `int(11) unsigned`, `enum('M','F')` (fingerprint)
	bool nullable = false;
	bool auto_increment = false;
	std::string charset;     ///< CHARACTER_SET_NAME; empty for non-text columns
};

struct SourceTable {
	std::string name;
	std::vector<SourceColumn> columns;
	std::uint64_t auto_increment = 0; ///< information_schema.TABLES.AUTO_INCREMENT (0 = none)
};

/// A source value exactly as stored (read over a binary connection); nullopt is SQL NULL.
using RawValue = std::optional<std::string>;
using RawRow = std::vector<RawValue>;

class LegacySource {
public:
	virtual ~LegacySource() = default;
	/// For messages; never contains the password.
	[[nodiscard]] virtual std::string describe() const = 0;
	virtual std::vector<SourceTable> tables() = 0;
	virtual std::uint64_t row_count(const SourceTable& table) = 0;
	/// Streams every row of `table`, restricted to `columns` in that order, to `sink` in batches
	/// of at most `batch_size` rows. With `utf8_as_latin1`, utf8/utf8mb4 text columns are read
	/// converted to latin1 (for servers that wrote latin1 bytes through a latin1 connection into
	/// utf8 tables); otherwise every value is the stored bytes.
	virtual void read_rows(const SourceTable& table, const std::vector<const SourceColumn*>& columns,
	                       bool utf8_as_latin1, std::size_t batch_size,
	                       const std::function<void(std::vector<RawRow>&)>& sink) = 0;
};

// ------------------------------------------------------------------ target (PostgreSQL / SQLite)

enum class TargetType { Integer, Real, Text, Blob, Timestamp, Date };

struct TargetColumn {
	std::string name;
	TargetType type = TargetType::Text;
	bool nullable = true;
	std::optional<std::string> default_literal; ///< the quoted literal of DEFAULT '...', if any
	std::vector<std::string> allowed;           ///< CHECK ("col" IN (...)) values; empty = any
	std::size_t max_length = 0;                 ///< varchar(n) limit in bytes (PostgreSQL); 0 = none
	bool identity = false;                      ///< PostgreSQL identity / SQLite AUTOINCREMENT key
};

struct TargetTable {
	std::string name;
	std::vector<TargetColumn> columns;
	std::uint64_t rows = 0;
	[[nodiscard]] const TargetColumn* find(std::string_view column) const noexcept;
};

struct TargetSchema {
	std::vector<TargetTable> tables;
	std::vector<std::pair<std::string, std::string>> foreign_keys; ///< (child table, parent table)
	std::string encoding; ///< PostgreSQL server encoding; empty on SQLite
	[[nodiscard]] const TargetTable* find(std::string_view table) const noexcept;
};

/// Reads tables, columns, CHECK value lists, foreign keys and row counts of the connected
/// database (PostgreSQL: the current schema).
TargetSchema inspect_target(SqlConnection& conn);

// ------------------------------------------------------------------ pure parts (unit-tested)

/// Column type from PostgreSQL information_schema.columns.data_type, or SQLite's declared type.
TargetType target_type(std::string_view declared, SqlDialect dialect);

/// All '...' literals in `sql`, unescaped ('' -> ').
std::vector<std::string> quoted_literals(std::string_view sql);

/// Values of a `CHECK ("column" IN ('a', 'b'))` clause inside a CREATE TABLE statement; empty if
/// there is none.
std::vector<std::string> check_in_values(std::string_view create_sql, std::string_view column);

/// Table names created by a generated schema file (`CREATE TABLE IF NOT EXISTS "name"`).
std::set<std::string> schema_file_tables(std::string_view schema_sql);

/// Default rows a generated schema file inserts, per table (`INSERT ... INTO "name"`): the server
/// account in login, the clans, the roulette prizes. A table holding no more rows than this is
/// treated as freshly created; the source's rows replace the defaults.
std::map<std::string, std::uint64_t> schema_file_seed_rows(std::string_view schema_sql);

/// MySQL zero or partial-zero dates ('0000-00-00', '2024-00-10 ...') cannot be stored elsewhere.
bool is_zero_date(std::string_view value) noexcept;

struct ColumnPlan {
	std::vector<std::pair<std::size_t, std::size_t>> copy; ///< (source index, target index)
	std::vector<std::string> source_only;                 ///< dropped: not in the target
	std::vector<std::string> target_only;                 ///< left to the target's default
};
/// Columns matched by name (case-insensitively), in target order.
ColumnPlan plan_columns(const SourceTable& source, const TargetTable& target);

/// `tables` sorted by name, then reordered so every parent of a foreign key comes before its
/// children. Cycles keep the alphabetical order.
std::vector<std::string> copy_order(std::vector<std::string> tables,
                                    const std::vector<std::pair<std::string, std::string>>& foreign_keys);

struct Converted {
	SqlValue value;
	std::string adjustment; ///< empty if the value was copied as is; otherwise what was done
};
/// Turns one source value into the value bound for `target`:
///  - zero dates become NULL (nullable column) or 1970-01-01 [00:00:00];
///  - a value outside the column's CHECK list becomes the column default (or NULL, or the first
///    allowed value) -- MySQL stores '' for an invalid enum;
///  - NULL in a NOT NULL column becomes the type's zero value;
///  - text is cut at a NUL byte (C strings in the legacy servers) and at varchar(n) bytes;
///  - integer columns are bound as integers, blobs as Blob, everything else as the raw text.
Converted convert_value(const SourceColumn& source, const TargetColumn& target, const RawValue& raw);

// ------------------------------------------------------------------ the import

struct ImportOptions {
	std::filesystem::path schema_dir = "sql-files";
	std::size_t batch_size = 1000;
	std::set<std::string> known_baselines; ///< accepted source fingerprints
	bool utf8_as_latin1 = false;            ///< see LegacySource::read_rows
};

struct TableReport {
	enum class Status { Ok, Mismatch, KeptDefaults, NoCommonColumns };
	std::string table;
	Status status = Status::Ok;
	std::uint64_t source_rows = 0;
	std::uint64_t target_rows = 0;
	std::uint64_t failed_rows = 0;
	std::vector<std::string> errors;                      ///< first few row errors
	std::map<std::string, std::uint64_t> adjustments;     ///< "column: what" -> count
	std::vector<std::string> notes;                       ///< dropped / defaulted columns
};

struct ImportReport {
	bool refused = false;
	std::string refusal;
	std::string fingerprint;
	bool created_schema = false;
	std::vector<TableReport> tables;
	std::vector<std::string> source_only; ///< skipped: no such table in the target
	std::vector<std::string> target_only; ///< not in the source: left as created
	[[nodiscard]] bool ok() const noexcept;
	[[nodiscard]] std::uint64_t rows_copied() const noexcept;
};

/// Runs the import; progress lines go to `progress`. Refusals (unknown source schema, unusable
/// target) come back in the report before anything is written.
ImportReport run_import(LegacySource& source, SqlConnection& target, const ImportOptions& options,
                        std::ostream& progress);

void print_summary(const ImportReport& report, std::ostream& out);

} // namespace rathena::persistence::migrate
